css:
.border-frame {
  font-size: 16px;
  margin: 0 auto 2em;
  padding: 2em;
  background-color: #fff;
  box-shadow: 0 0 6px 1px #FFFACD, 0 0 6px 1px #FFFACD inset;
  border-radius: 30px;
}

.border-frame p {
  margin: 0;
}

.blend {
  display: flex;
  justify-content: center;
  padding: 50px 0;
}

.blend .shape {
  box-sizing: border-box;
  color: #fff;
  font-size: 16px;
  width: 200px;
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  mix-blend-mode: multiply;
  margin-left: -30px;
}

.blend .shape:first-child {
  margin-left: 0;
}

.shape1 {
  background: #ffc0cb;
  border-radius: 70% 60% 50% 50% / 50% 60% 70% 80%;
}

.shape2 {
  background: #e94e77;
  border-radius: 70% 50% 70% 60% / 40% 80% 60% 70%;
}

.shape3 {
  background: #ffb6c1;
  border-radius: 60% 70% 60% 70% / 70% 60% 70% 60%;
}

.box {
  font-size: 16px;
  padding: 1.35em 1.5rem;
  border-top-left-radius: 30px;
  border-bottom-right-radius: 30px;
  border: 5px solid #f28ca9;
  background-color: #ffe4e9;
}

.box p {
  font-size: 1em;
  color: #333;
  line-height: 1.5;
}

 .box {
  font-size: 16px;
  width: min(750px, 100%);
  margin: 0 auto;
}


@media (max-width: 500px) {
 .box {
  font-size: 3.3vw;
}
}

 .box-border {
  padding: 1.5em;
  border: 3px solid #EEE;
  border-radius: 10px;
}

 .box-title {
  font-size: 1.2em;
  line-height: 1.2;
  font-weight: 600;
}

 .box-text {
  line-height: 1.5;
  margin-top: .5em;
}

 .box-check {
  margin-top: 1em;

}

 .box-check input {
  display: none;
}

 .box-check label {
  font-size: 1.025em;
  line-height: 1.5;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 0.5em;
  position: relative;
  width: fit-content;
  margin: 0 auto;
}

 .box-check label::before,
 .box-check label::after {
  content: "";
  display: block;
  width: 20px;
  aspect-ratio: 1;
  border: 3px solid #EEE;
  border-radius: 5px;

}

 .box-check label::after {
  background-color: #000;
  position: absolute;
  top: 0;
  left: 0;
  scale: 0.7;
  border-radius: 5px;
  opacity: 0;
}

 .box-check input:checked+label::after {
  opacity: 1;
}

 .note {
  font-size: 0.8em;
  line-height: 1.5;
  font-weight: 600;
  margin-top: 1em;
  text-align: center;
}

 .border-box {
  width: 100%;
  padding: 5%;
  border: 5px solid #ff0000;
  background-color: #ffffff;
  color: #000000;
  font-size: 25px;
  font-weight: bold;
  text-align: center;
  position: relative;
  box-sizing: border-box;
}

 .border-box.blink {
  animation: border-blink 1s infinite;
}

 .border-box.blink::before {
  border-top: 5px solid #FF0000;
  border-left: 5px solid #FF0000;
  content: '';
  display: block;
  position: absolute;
  top: -5px;
  left: -5px;
  width: 20px;
  height: 20px;
  z-index: 1;
}

@keyframes border-blink {
  50% {
    border-color: transparent;
  }
}

@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@100..900&display=swap');

.repute__wrap {
  font-size: 16px;
  max-width: min(750px, 96%);
  margin-inline: auto;
  font-family: "Noto Sans JP", sans-serif;
  font-optical-sizing: auto;
  color: #5f5041;
  border-radius: 8px 8px 0 0;
  overflow: hidden;
  background-color: #FEFAD2;
  padding: 2em 1.5em;
}
@media (max-width: 500px) {
   .repute__wrap {
    font-size: 3.4vw;
  }
}
 .repute__head {
  padding: 2% 3% 2% 0;
  text-align: center;

}

 .repute__head_title {
  font-size: 1.5em;
  font-weight: bold;
}

 .repute__content {
  padding: 0 15px;
  overflow: hidden;
  position: relative;
  background-color: #eda5a6;
}

 .repute__content [class*=repute-swiper-button-] {
  width: 30px;
  height: 30px;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: 0%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: #ed7f81;
  border-radius: 50%;
  overflow: hidden;
  z-index: 10;
}

 .repute__content [class*=repute-swiper-button-]::before {
  content: "";
  width: 100%;
  height: 100%;
  scale: .5;
  background-color: #ffffff;
  clip-path: polygon(75% 0, 40% 50%, 75% 100%, 55% 100%, 20% 50%, 55% 0);
}

 .repute__content .repute-swiper-button-next {
  left: unset;
  right: 0%;
}

 .repute__content .repute-swiper-button-next::before {
  clip-path: polygon(35% 0, 77% 50%, 35% 100%, 15% 100%, 58% 50%, 15% 0);
}

 .repute-swiper-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1em;
  position: absolute;
  bottom: 0.5em;
  width: fit-content;
  left: 50%;
  translate: -50% 0;
}

 .repute-swiper-pagination span {
  width: 15px;
  aspect-ratio: 1;
  background-color: #FFF;
  display: inline-block;
  border-radius: 50%;
}

 .repute-swiper-pagination span.swiper-pagination-bullet-active {
  background-color: #fded8d;
}

 .repute__inner {
  margin: 2em 0;
  overflow: hidden;
  position: relative;
}

 .repute__ratings {
  position: relative;
  font-size: 22px;
  min-height: 22px;
  line-height: 1;
  margin-bottom: 5px;
  margin-left: 10px;
}

 .repute__ratings::before,
 .repute__ratings::after {
  content: "★★★★★";
  color: #ffe683;
  position: absolute;
  top: 0;
  left: 0;
}

 .repute__ratings::after {
  color: #ffb448;
  overflow: hidden;
  white-space: nowrap;
}

 .repute__item {
  border-radius: 1em;
  padding: 2em;
  background-color: #FFF;
}

 .repute__item:has(img) {
  display: grid;
  align-items: center;
  gap: 5px;
  grid-template-columns: 3.5em auto;
  grid-template-rows: 1.5em auto auto;
}

 .repute__item .icon {
  width: 3.5em;
  aspect-ratio: 1;
  object-fit: contain;
  grid-column: 1 / 2;
  grid-row: 1 / 3;
  border-radius: 50%;
  background-color: #EEE;
}

 .repute__title {
  font-size: 1.15em;
  font-weight: bold;
  grid-column: 2 / 3;
  line-height: 1;
  margin-left: 10px;

}

 .repute__comment {
  text-align: justify;
  grid-column: 1 / -1;
  padding-top: .5em;

}

 .repute__ratings[data-ratings="0"]::after {
  width: 0px;
}

 .repute__ratings[data-ratings="0.5"]::after {
  width: calc(22px * 0.5);
}

 .repute__ratings[data-ratings="1"]::after ,
 .repute__ratings[data-ratings="1.0"]::after{
  width: 22px;
}

 .repute__ratings[data-ratings="1.5"]::after {
  width: calc(22px * 1.5);
}

 .repute__ratings[data-ratings="2"]::after,
 .repute__ratings[data-ratings="2.0"]::after {
  width: calc(22px * 2);
}

 .repute__ratings[data-ratings="2.5"]::after {
  width: calc(22px * 2.5);
}

 .repute__ratings[data-ratings="3"]::after ,
 .repute__ratings[data-ratings="3.0"]::after{
  width: calc(22px * 3);
}

 .repute__ratings[data-ratings="3.5"]::after {
  width: calc(22px * 3.5);
}

 .repute__ratings[data-ratings="4"]::after,
 .repute__ratings[data-ratings="4.0"]::after {
  width: calc(22px * 4);
}

 .repute__ratings[data-ratings="4.5"]::after {
  width: calc(22px * 4.5);
}

 .repute__ratings[data-ratings="5"]::after,
 .repute__ratings[data-ratings="5.0"]::after{
  width: calc(22px * 5);
}

 .swiper-wrapper {
  position: relative;
  width: 100%;
  height: auto !important;
  z-index: 1;
  display: flex;
  transition-property: transform;
  box-sizing: content-box;
}

 .swiper-android .swiper-slide,
 .swiper-wrapper {
  transform: translate3d(0px, 0, 0);
}

 .swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: auto !important;
  position: relative;
  transition-property: transform;
}

 .repute.js-repute-slide.init .swiper-wrapper {
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
}

 .repute.js-repute-slide.init .swiper-slide {
  scroll-snap-align: start;
}

 * {
  box-sizing: border-box;
}

 .widget-container {
  font-size: 16px;
  width: 100%;
}

@media (max-width: 550px) {
   .widget-container {
    font-size: 3.3vw;
  }
}

 .contact-contents {
  position: relative;
  width: 100%;
  background: no-repeat center/cover;
  background-image: url("/uploads/3728332121f640e183deea4d2c87cb1712b1405c8bbb5ba8f53a2ca4eb8f911c.webp");
}

 .contact-contents-inner {
  position: relative;
  z-index: 2;
  width: min(90%, 750px);
  margin-inline: auto;
  display: grid;
  place-content: center;
  text-align: center;
  padding: 2.5em 0;
  gap: 1.5em;
}

 .contact-contents .title {
  font-size: 2em;
  font-weight: 600;
  line-height: 1.2;
}

 .contact-contents .description {
  font-size: 1.0em;
  margin-top: 0.5em;
}

 .contact-contents .info {
  display: flex;
  flex-direction: column;
  gap: 1em;
}

 .contact-contents .tel-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1em;
}

 .contact-contents .tel-title {
  font-size: 1em;
  font-weight: 600;
}

 .contact-contents .number a {
  font-size: 1.8em;
  font-weight: 700;
  line-height: 1;
  color: #000;
}

 .contact-contents .caption {
  font-size: 0.8em;
  line-height: 1;
  color: #666;
  text-align: left;
}

 .btn {
  text-decoration: none !important;
  display: inline-block;
  width: 100%;
  padding: 1em 0;
  background-color: #008061;
  border-radius: 0.25em;
  color: #fff;
  font-weight: 600;
  font-size: 1.2em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1em;
  filter: drop-shadow(0px 0px 3px rgba(0, 0, 0, 0.4));
  position: relative;
}

 .btn::before,
 .btn::after {
  content: "";
  display: inline-block;
}

 .btn::before {
  width: 1.25em;
  aspect-ratio: 9/7;
  mask: url("/uploads/b45cab8530a40356b7a9a40985a6afde492f2ffe46d7a3dc57aba3762b60050f.svg") no-repeat center/contain;
  background-color: currentColor;
  mask-size: 100%;
}

 .btn::after {
  width: 0.75em;
  aspect-ratio: 3/4;
  clip-path: polygon(0 0, 0% 100%, 100% 50%);
  background-color: currentColor;
  position: absolute;
  top: 50%;
  right: 7.5%;
  transform: translateY(-50%);
}

@media (max-width: 550px) {
   .contact-contents {
    padding: 5em 0;
  }

   .contact-contents .tel-wrap {
    flex-direction: column;
    gap: 0.5em;
  }

   .contact-contents .caption {
    text-align: center;
  }
}

 a {
  text-decoration: none !important;
}

 * {
  box-sizing: border-box;
}

 .wrap {
  width: 540px;
  margin: 30px auto 0;
  padding: 0 0 40px;
  background-color: #e7f5f7;
  text-align: center;
  font-family: serif;
  position: relative;
}

 .wrap+.wrap {
  margin: 0 auto;
}

 .wrap+.wrap .title {
  top: 0;
}

 .wrap+.wrap .imagesbox {
  margin: 25px auto 30px;
}

 h2.title {
  background: #5bbdca;
  color: #ffffff;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  margin: 0 auto;
  padding: 3px 20px;
  display: inline-block;
  text-align: center;
  width: 300px;
  position: relative;
  top: -20px;
  box-sizing: border-box;
}

 .imagesbox {
  display: flex;
  gap: 10px;
  width: 74%;
  margin: 5px auto 25px;
}

 .imagesbox .image {
  width: 50%;
  border-radius: 14px 0px 14px 14px;
  overflow: hidden;
  position: relative;
}

 .imagesbox .image img,
 .imagesbox .image video {
  width: 100%;
  margin: 0 !important;
  vertical-align: bottom;
}

 .imagesbox .image.before::before,
 .imagesbox .image.after::before {
  width: 70px;
  height: 22px;
  color: #ffffff;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0.1em;
  line-height: 1.4;
  position: absolute;
  top: 0;
  right: 0;
  display: flex;
  justify-content: center;
  align-items: center;
}

 .imagesbox .image.before::before {
  content: "before";
  background-color: #828181;
}

 .imagesbox .image.after::before {
  content: "after";
  background-color: #ea8037;
}

 .imagesbox .arrow {
  width: 15px;
  position: relative;
  flex-shrink: 0;
}

 .imagesbox .arrow::before {
  content: "";
  width: 0;
  height: 0;
  position: absolute;
  top: calc(50% - 20px);
  left: 0;
  right: 0;
  display: inline-block;
  border-style: solid;
  border-width: 20px 0 20px 15px;
  border-color: transparent transparent transparent #ea8037;
}

 .textbox {
  width: 70%;
  margin: 0 auto;
  border-bottom: 1px dashed #959494;
  text-align: left;
}

 .textbox .text {
  color: #333333;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.28;
  text-decoration: underline;
}


@media (max-width: 500px) {
   h2.title {
    font-size: 16px;
    padding: 3px 15px;
  }

   .textbox .text {
    font-size: 14px;
  }
}

 .widget-container {
  font-size: 16px;
  font-family: serif;
  width: min(100%, 750px);
  margin-inline: auto;
}

@media (max-width: 500px) {
   .widget-container {
    font-size: 3.3vw;
  }
}

 .price-section {
  background: #e7f5f7;
}

 .price-section__title {
  font-size: 1.5em;
  color: #549ea9;
  background: rgba(255, 255, 255, 0.502);
  display: grid;
  place-items: center;
  text-align: center;
  padding-block: 0.5em;
}

 .price-section__title .title-text {
  width: fit-content;
  margin-inline: auto;
}

 .price-section__title .title-text::before,
 .price-section__title .title-text::after {
  content: "";
  display: block;
  width: calc(100% + 3em);
  height: 5px;
  margin-inline: -1em;
  mask-image: url("/uploads/4082b636750f972fd45ab4ca16160ad587f8de715aa28ffc3553c6077168ad21.svg");
  mask-repeat: no-repeat;
  mask-position: center;
  mask-size: contain;
  background: #549ea9;
  padding-block: 0.35em;
}

 .price-section__content {
  margin-top: 5.5em;
  padding: 0 2em 2em;
  background: rgba(255, 255, 255, 0.502);
}

 .price-section__content-title {
  width: fit-content;
  margin-inline: auto;
  font-size: 1.35em;
  text-align: center;
  background: linear-gradient(90deg, #dfd3bd 0%, #e5d5b6 0%, #d9ece4 48%, #ace7ee 100%);
  border-radius: 99px;
  padding: 0.5em 1.75em;
  translate: 0 -50%;
}

@media (max-width: 500px) {
   .price-section__content-title {
    width: 100%;
    font-size: 1.25em;
  }
}

 .price-section__content-list {
  display: grid;
  gap: 1em;
  padding: 2em;
}

@media (max-width: 500px) {
   .price-section__content-list {
    padding: 0;
  }
}

 .price-section__content-item {
  display: flex;
  align-items: center;
  gap: 1em;
}

 .price-section__content-item.highlight .title::before {
  background-color: #b2622b;
}

 .price-section__content-item.highlight .title::after {
  background-color: #ea8037;
}

 .price-section__content-item.highlight .price {
  color: #ea8037;
}

 .price-section__content-item:not(:last-child) {
  padding-bottom: 1em;
  border-bottom: 1.5px dotted #666;
}

 .price-section__content-item .title {
  color: #fff;
  position: relative;
  z-index: 1;
  padding: 0.5em 0 0.25em 1em;
  white-space: nowrap;
}

 .price-section__content-item .title::before,
 .price-section__content-item .title::after {
  content: "";
  display: block;
  width: 100%;
  height: 100%;
  clip-path: polygon(0 0, 100% 0%, 85% 100%, 0% 100%);
  padding: 0 1em 0;
  position: absolute;
  top: 0;
  left: 0;
}

 .price-section__content-item .title:before {
  z-index: 0;
  background-color: #569daa;
  top: 4px;
  left: 4px;
}

 .price-section__content-item .title:after {
  z-index: 5;
  background-color: #64b7c6;
}

 .price-section__content-item .title-text {
  font-size: 1.5em;
  position: relative;
  z-index: 10;
}

 .price-section__content-item .price {
  font-size: 1.85em;
  line-height: 1.25;
  width: min(30%, 150px);
  letter-spacing: 0.1em;
  white-space: nowrap;
  position: relative;
  display: grid;
  place-content: end;
}

 .price-section__content-item .separator {
  width: auto;
  height: 0.5px;
  background-color: #636363;
  z-index: 1;
  margin-left: -.5em;
  flex: 1;
}

 .price-section__content-item .caption {
  font-size: 12px;
  letter-spacing: 0.05em;
}


@media (max-width: 600px) {
   .price-section__content-item .title-text {
    font-size: 1.35em;
  }

   .price-section__content-item .price {
    font-size: 1.35em;
  }

   .price-section__content-item .caption {
    font-size: 2vw;
    position: absolute;
    bottom: -1.25em;
  }
}

 * {
  box-sizing: border-box;
}

 .banner-container {
  font-size: 16px;
  font-family: serif;
  width: min(100%, 750px);
  margin-inline: auto;
  line-height: 1.35;
  background-color: #fff;
}

@media (max-width: 500px) {
   .banner-container {
    font-size: 3vw;
  }
}

 .banner-logo {
  width: 280px;
  margin-inline: auto;
  background-color: #fff;
  padding: 2.5em 0 1em;
  position: relative;
  z-index: 10;
}

 .banner-title {
  margin-top: -5.5em;
  background: linear-gradient(0deg, #6bbbc6, #f5f9fa 66%, #fff);
  clip-path: polygon(0 0, 100% 0%, 100% 62%, 50% 100%, 0 62%);
  padding: 3.5em 0 8.5em;
  text-align: center;
  position: relative;
  z-index: 5;
}

 .banner-title .text {
  font-size: 2.25em;
  translate: 0 1.25em;
}

 .banner-image {
  width: 100%;
  aspect-ratio: 580/883;
  position: relative;
  z-index: 1;
  margin-top: -20%;
}

 .banner-image img {
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

@media (max-width: 500px) {
   .banner-image {
    margin-top: -25%;
  }
}

 .banner-points {
  width: 80%;
  position: absolute;
  top: 75%;
  left: 50%;
  translate: -50% -50%;
  z-index: 10;
}

 .banner-points .point {
  width: 100%;
  font-size: 1.5em;
  font-weight: bold;
  background-color: rgba(234, 128, 55, 0.902);
  color: #fff;
  border-radius: 99px;
  padding: 0.5em 1em;
  text-align: center;
}

 .banner-points .point:not(:first-child) {
  margin-top: 0.5em;
}

 * {
  box-sizing: border-box;
}

 .wrap {
  width: 540px;
  margin: 0 auto;
  padding: 30px 0;
  text-align: center;
  font-family: serif;
  position: relative;
}

 .head {
  width: 100%;
  padding: 0 5%;
  box-sizing: border-box;
  position: absolute;
  z-index: 1;
}

 .head::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 60%;
  background-color: rgba(255, 255, 255, 0.7);
  top: 0;
  left: 0;
  z-index: -1;
}

 .head::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100px;
  clip-path: polygon(0 0, 50% 100%, 100% 0);
  background-color: rgba(255, 255, 255, 0.7);
  top: calc(60% - 0.5px);
  left: 0;
  z-index: -1;
}

 .head .title {
  color: #333333;
  font-size: 36px;
  font-weight: 400;
  line-height: 1.4;
  margin: 0;
}

 .head .lead {
  color: #333333;
  font-size: 20px;
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: 0.05em;
  margin: 5px 0 0;
}

 .image {
