  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.1em 1em;
}

.tbl-transition {
  width: 100%;
  text-align: left;
  vertical-align: middle;
  border-collapse: collapse;
  box-sizing: border-box;
}

.tbl-transition th,
.tbl-transition td {
  font-size: clamp(13px, 2.66vw, 16px);
  padding: 0.5em;
  box-sizing: border-box;
}

.tbl-transition thead th .tag {
  font-size: clamp(12px, 2.5vw, 15px);
  font-weight: normal;
  line-height: 1;
  white-space: nowrap;
  padding: 0.8em 1em;
  background-color: #ffffff;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}

.tbl-transition thead th.after {
  width: 100%;
  padding-left: 2em;
}

.tbl-transition thead th.after .tag {
  font-weight: bold;
  color: #E05151;
}

.tbl-transition tbody tr {
  border-bottom: 1px dotted #dddddd;
}

.tbl-transition tbody tr:last-child {
  border-bottom: none;
}

.tbl-transition tbody th {
  font-size: clamp(11px, 2.33vw, 14px);
  white-space: nowrap;
  color: #00afcc;
  font-weight: bold;
  padding-right: 0.5em;
}

.tbl-transition tbody td {
  position: relative;
}

.tbl-transition tbody td.before {
  min-width: 6em;
  padding-right: 1em;
}

.tbl-transition tbody td.after {
  padding-left: 2em;
  font-weight: bold;
}

.tbl-transition tbody td.after::before {
  content: "";
  display: inline-block;
  width: 0.8em;
  height: 0.8em;
  border-top: 2px solid #E05151;
  border-right: 2px solid #E05151;
  transform: rotate(45deg);
  position: absolute;
  left: 0;
  top: calc(50% - 0.5em);
}

