.faq-item[open] .faq-question::after {
  rotate: 180deg;
}

.faq-item[open] .faq-answer {
  /*animation: fadeIn .5s ease-in-out .25s forwards;*/
  opacity: 1;
  transform: translateY(0px);
}

.faq-question {
  cursor: pointer;
  position: relative;
  padding: 1em 2.5em 1em 1em;
  font-weight: 800;
  transition: 0.5s;
}

.faq-question::after {
  content: "";
  position: absolute;
