  right: 1.5em;
  transition: 0.5s;
  width: .75em;
  height: .75em;
  border-bottom: 4px solid #4f5ed2;
  border-right: 4px solid #4f5ed2;
  transform: rotate(45deg);
}

.faq-answer {
  font-weight: 400;
  padding: 1em 1em;
  background-color: #fff5f4;
  margin: .5em 0;
  opacity: 0;
  transform: translateY(-10px);
  animation-delay: .5s;
  transition-property: transform;
}

summary {
