.rank-head {
  position: relative;
  width: 100%;
  border-top: solid 5px #333;
}

.rank-head::before {
  content: attr(data-rank) "";
  width: 40px;
  height: 40px;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  background-color: #333;
  -webkit-clip-path: polygon(0 0, 100% 0, 100% 100%, 50% 75%, 0 100%);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 50% 75%, 0 100%);
  font-weight: bold;
  font-family: system-ui;
  color: #FFF;
  line-height: 1.5;
  position: absolute;
  top: -20px;
  left: 10px;
  padding-top: 5px;
  z-index: 10;
}

.rank-head::after {
  content: "";
  width: 20px;
  height: 15px;
  background-color: #000;
  -webkit-clip-path: polygon(60% 100%, 0 0, 0 100%);
  clip-path: polygon(60% 100%, 0 0, 0 100%);
  position: absolute;
  top: -20px;
  left: 50px;
}

