/* 全体の設定 */
.cardBox__area {
  /* 横幅 */
  width: 100%;
  /* 外側の余白｜上下｜左右（センタリング）｜ */
  margin: 0 auto;
}



/* 内側の設定 */
.cardBox__area .cardBox__inner {
  /* 上線｜太さ｜線種｜色｜ */
  border-top: 5px solid #000;
  /* 左線｜太さ｜線種｜色｜ */
  border-left: 5px solid #000;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: flex-start;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる
  stretch = 隣の要素の高さと揃える*/
  align-items: stretch;
  /* 横幅が100％超えた時は改行する */
  flex-wrap: wrap;
}



/* 1つずつの箱 */
.cardBox__inner .cardBox {
  /* 線｜太さ｜線種｜色｜ */
  border-right: 5px solid #000;
  /* 線｜太さ｜線種｜色｜ */
  border-bottom: 5px solid #000;
  /* 横幅（1行=100%, 2行=50％）、線分の5pxを引いてください */
  width: calc(50% - 5px);
  /* 高さ */
  height: auto;
}



/* テキストと平均金額部分 */
.cardBox .top__area {
  /* 高さ（テキスト部分の改行に合わせて高さを設定してください） */
  height: 3rem;
  /* 線｜太さ｜線種｜色｜ */
  border-bottom: 1px dashed #ccc;
  /* 内側の余白  */
  padding: 5px;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: space-between;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる*/
  align-items: center;
}



/* テキスト部分 */
.cardBox .top__area .name {
  /* 横幅（全体から金額部分を引いた幅） */
  width: calc(100% - 120px);
  /* 行間 */
  line-height: 1.1;
  /* 文字の大きさ */
  font-size: 24px;
  /* 文字の太さ */
  font-weight: bold;
  /* 外側の余白 */
  margin: 0;
}



/* 小さい文字 */
.cardBox .top__area .name.small,
.cardBox .top__area .name .small {
  /* 文字の大きさ */
  font-size: 18px;
  display: inline-block;
}



/* 金額部分 */
.cardBox .top__area .price {
  /* 横幅 */
  width: 105px;
  /* 背景色 */
  background: #000;
  /* 文字色 */
  color: #fff;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の大きさ */
  font-size: 14px;
  /* 内側の余白  */
  padding: 0 3px;
  /* 外側の余白 */
  margin: 0;
  /* 線｜太さ｜線種｜色｜ */
  border-radius: 3px;
  /* 文字間 */
  letter-spacing: -0.05em;
  /* 文字の位置 */
  text-align: center;
}



/* 金額の数字部分 */
.cardBox .top__area .price .num {
  /* 文字の大きさ */
  font-size: 24px;
}



/* 画像部分 */
.cardBox .btm__area {
  /* 内側の余白  */
  padding: 5px;
}



/* 画像 */
.cardBox .btm__area img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* PCサイズの時のみ表示する */
.pcOnly {
  display: block;
}



/* PCサイズの時のみ非表示にする */
.spOnly {
  display: none;
}

/* 画面サイズに合わせた設定、適宜数値を設定してください（レスポンシブ） */
@media screen and (max-width:600px) {


  /* 1つずつの箱 */
  .cardBox__inner .cardBox {
    /* 横幅（1行=100%, 2行=50％）、線分の5pxを引いてください */
    width: calc(50% - 5px);
  }



  /* テキストと平均金額部分 */
  .cardBox .top__area {
    flex-wrap: wrap;
    /* 高さ */
    height: inherit;
  }



  /* テキスト部分 */
  .cardBox .top__area .name {
    /* 横幅 */
    width: 100%;
    min-height: 3.3rem;
  }



  /* 金額部分 */
  .cardBox .top__area .price {
    /* 横幅 */
    width: 100%;
    max-width: 115px;
    margin-top: 5px;
  }



  /* SPサイズの時のみ非表示する */
  .pcOnly {
    display: none;
  }



  /* SPサイズの時のみ表示にする */
  .spOnly {
    display: block;
  }
}

