/*スマートフォンの枠の設定*/
.spMockBox {
  position: relative;
  /*widgetの外側の余白。1番目の値は上下余白、2番目の値は左右余白（auto=真ん中寄せ）*/
  margin: 0 auto;
  /*スマートフォン枠の横幅（横幅を変更する場合は、必ず★マークがついてる部分の値を同じ値に変更してください）
  ※以下を変更した場合、変更は3箇所あります*/
  width: 300px;
  /* ★ スマートフォン枠の高さ（「スマートフォン枠の横幅」を変更した場合は、「300」の部分を変更した横幅の値と同じ値にしてください。）*/
  height: calc(300px * 2.008);
  max-width: 100%;
  line-height: 1;
  pointer-events: none;
}

.spMockBox:before {
  content: '';
  width: 100%;
  display: block;
  padding-bottom: 200.8%;
  position: absolute;
  /*スマートフォンの画像
  ※画像を変更すると、横幅や高さなど再計算が必要になる可能性がありますのでご注意ください*/
  background-image: url("/uploads/f388aed77d1878b18fb3d3c19addc2ad25edb3aa2aa8693905e51358f45e31b9.png");
  background-size: contain;
  background-repeat: no-repeat;
  z-index: 10;
}



/*動画の設定*/
.spMockBox>video,
.spMockBox>img {
  /* ★ 動画の横幅（「スマートフォン枠の横幅」を変更した場合は、「300」の部分を変更した横幅の値と同じ値にしてください。）*/
  width: calc(300px * 0.875);
  /* ★ 動画の高さ（「スマートフォン枠の横幅」を変更した場合は、「300」の部分を変更した横幅の値と同じ値にしてください。）*/
  height: calc((300px * 0.875) * 2.17) !important;
  /*動画の表示方法
  cover=動画の縦横比を維持しつつ、エリア内にフィットさせ、はみ出た部分はトリミングします。
  contain=動画の縦横比を維持しつつ、長辺がフィットします。短辺は余白ができます。*/
  -o-object-fit: cover;
  object-fit: cover;
  /*動画の表示位置（「object-fit: cover;」を使用時に利用できます）
  　1番目の値はX軸の値、2番目の値はY軸の値*/
  object-position: 30% 50%;
  margin: 0 !important;
  position: absolute;
  /*スマートフォン枠分、内側移動させています*/
  top: 2.6%;
  left: 6%;
  right: 2.6%;
  bottom: 6%;
  pointer-events: auto;
}

/*レスポンシブ時の設定
「記事設定」の配信Version幅で設定した値を「620px」部分に入力してください*/
@media screen and (max-width: 620px) {
  .spMockBox {
    /*スマートフォン枠の横幅（横幅を変更する場合は、必ず◆マークがついてる部分の値を同じ値に変更してください）
  　※以下を変更した場合、変更は1箇所あります*/
    width: 80%;
    height: 0;
    /* ◆ スマートフォン枠の高さ
    スマートフォン枠の横幅を変更した場合は、%の値を少数に直して「0.8」部分を変更してください
    （例：80% → 0.8）*/
    padding-bottom: calc(0.8 * 200.8%);
  }

  .spMockBox>video,
  .spMockBox>img {
    width: calc(100% - 12%);
    height: calc(100% - 5.2%) !important;
    /*動画の表示方法
    cover=動画の縦横比を維持しつつ、エリア内にフィットさせ、はみ出た部分はトリミングします。
    contain=動画の縦横比を維持しつつ、長辺がフィットします。短辺は余白ができます。*/
    -o-object-fit: cover;
    object-fit: cover;
    /*動画の表示位置（「object-fit: cover;」を使用時に利用できます）
  　1番目の値はX軸の値、2番目の値はY軸の値*/
    object-position: 30% 50%;
  }
}

